mapper.select:
SELECT id, object_key, ledger_id, created_at, attempts, last_attempt_at
FROM storage_purge_task
WHERE created_at < #{createdBefore}
  AND (last_attempt_at IS NULL OR last_attempt_at < #{attemptedBefore})
ORDER BY id
LIMIT #{limit}

mapper.update:
UPDATE deletion_ledger
SET status = 'COMPLETED', completed_at = #{now}
WHERE id = #{ledgerId}
  AND status = 'STORAGE_PENDING'
  AND NOT EXISTS (SELECT 1 FROM storage_purge_task t WHERE t.ledger_id = #{ledgerId})
